const WHATSAPP = "2348000000000"
const HOURS = { 0: [12, 18], 1: [8, 21], 2: [8, 21], 3: [8, 21], 4: [8, 21], 5: [8, 21], 6: [8, 21] } // day → [open, close)

// 1. lagosNow(date = new Date()) → { day, hour } in Africa/Lagos time (Intl.DateTimeFormat + formatToParts)
// 2. isOpen(date = new Date()) → true when Lagos hour is in [open, close) for that day
// 3. #status: "Open now" with class "badge open", or "Closed" with class "badge closed"
// 4. On submit (no reload): if the name is blank or the phone isn't /^0\d{10}$/, put
//    "Please enter your name and an 11-digit phone number." in #form-error.
//    Otherwise clear the error and set #wa's href to https://wa.me/WHATSAPP?text=<encoded>, where the text is:
//    "Hello Mama Put Kitchen, this is NAME (PHONE): MESSAGE"

function lagosNow(date = new Date()) {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Africa/Lagos", weekday: "short", hour: "numeric", hourCycle: "h23",
  }).formatToParts(date)
  const get = (type) => parts.find((p) => p.type === type).value
  const day = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].indexOf(get("weekday"))
  return { day, hour: Number(get("hour")) }
}

function isOpen(date = new Date()) {
  const { day, hour } = lagosNow(date)
  const [open, close] = HOURS[day]
  return hour >= open && hour < close
}

const status = document.querySelector("#status")
const open = isOpen()
status.textContent = open ? "Open now" : "Closed"
status.className = open ? "badge open" : "badge closed"

document.querySelector("#enquiry").addEventListener("submit", (e) => {
  e.preventDefault()
  const name = document.querySelector("#name").value.trim()
  const phone = document.querySelector("#phone").value.trim()
  const message = document.querySelector("#message").value.trim()
  const error = document.querySelector("#form-error")
  if (!name || !/^0\d{10}$/.test(phone)) {
    error.textContent = "Please enter your name and an 11-digit phone number."
    return
  }
  error.textContent = ""
  const text = `Hello Mama Put Kitchen, this is ${name} (${phone}): ${message}`
  document.querySelector("#wa").href = `https://wa.me/${WHATSAPP}?text=${encodeURIComponent(text)}`
})
